self.KB_CONTENT["card:753115"]={"id":"card:753115","ty":"card","sourceId":"753115","title":"『立沖帳目維護作業』的作業目的為何？","ver":"iGP","topic":"立沖帳目","keywords":["立沖帳目","科目","傳票","過帳"],"y":"explain","answer":"傳票輸入時科目有做立沖管理，過帳後立沖帳資料寫入此檔。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
