self.KB_CONTENT["card:750558"]={"id":"card:750558","ty":"card","sourceId":"750558","title":"『客戶帳款明細表』的作業目的為何？","ver":"iGP","topic":"明細表","keywords":["明細表","客戶","結帳","統計"],"y":"explain","answer":"依據客戶的角度，將一段期間內各客戶之未收帳款資料，依結帳日期順序統計列時方式列印成表。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
