self.KB_CONTENT["card:755966"]={"id":"card:755966","ty":"card","sourceId":"755966","title":"『客戶訂單明細表』的作業目的為何？","ver":"iGP","topic":"明細表","keywords":["明細表","客戶","訂單"],"y":"explain","answer":"由「客戶訂單建立作業」將客戶訂單資料，以資料清單格式列印成表。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
self.KB_CONTENT["card:753560"]={"id":"card:753560","ty":"card","sourceId":"753560","title":"『銷退單建立作業』中的『備註 (TZ007)』為何？","ver":"iGP","topic":"銷退單","keywords":["銷退單","單身","備註"],"y":"other","answer":"* 可點選(icon)或[F2]片語資料查詢。子單身資料處理","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
