self.KB_CONTENT["card:792026"]={"id":"card:792026","ty":"card","sourceId":"792026","title":"『製令成本建立作業(標準)』中的『本期轉出成本-材料 (TB018)』為何？","ver":"GP4以上","topic":"製令","keywords":["製令","材料","加工","人工"],"y":"other","answer":"本期轉出成本-材料 (TB018)* 預設本期轉出金額=本期轉出成本-材料+本期轉出成本-人工+本期轉出成本-製費+本期轉出成本-加工。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
