self.KB_CONTENT["field:782650"]={"id":"field:782650","ty":"field","sourceId":"782650","title":"生效日期","ver":"GP4以上","topic":"","keywords":[],"job":"E-BOM 轉 BOM 維護","code":"MM003","answer":"* 表示一主件之組成元件資料自此日期開始生效。* 預設上一筆生效日期，亦可修改，點選或[F2]日期快手查詢。","file":"fields.jsonl"};
